// #241 slice 3 — an INDEXED rotary job in the simulation turns the stock to each face's A.
//
// The §6 fixture's shape (two flats, 1 mm deep on ⌀20), generated by the indexed CAM and posted, is
// opened through the panel's own door (the file chooser), simulated on the exact sweeper, and
// scrubbed and played across its index turn. The faces are 0° and 90° here — a 180° turn of a rod
// with a flat on each side looks the same in a picture, a quarter turn does not.
import fs from 'node:fs';
import path from 'node:path';
import type { Page } from '@playwright/test';
import { test, expect, enterCnc } from './fixtures/caseMaker';
import { generateIndexed } from '@/engine/cnc/cam/indexed';
import { postZ1 } from '@/engine/cnc/post/z1';
import { Z1 } from '@/engine/cnc/machine';
import { flatEndMill } from '@/engine/cnc/tool';

test.setTimeout(300_000);
const SHOTS = path.resolve(process.cwd(), '..', 'docs', 'bench', 'img', '2026-10-31-241-viewport');
const OUT = path.join(process.cwd(), 'test-results', 'sim-indexed-turn');

const RADIUS = 10;
const LENGTH = 30;
const TOOL = flatEndMill(3.175, { shoulderLength: 12, fluteLength: 12 });
const FROM_X = 3.175 / 2 + 3;
const TO_X = LENGTH - 3.175 / 2;

function twoFacesGcode(): string {
  const ir = generateIndexed({
    radius: RADIUS,
    faces: [
      { a: 0, fromX: FROM_X, toX: TO_X, depth: 1 },
      { a: 90, fromX: FROM_X, toX: TO_X, depth: 1 },
    ],
    tool: TOOL,
    params: { rpm: 12000, feed: 800, plungeFeed: 200, stepDown: 1, stepOver: 1, peck: 1, air: true },
    rapid: Z1.rapidEstimate,
  });
  const posted = postZ1(
    ir,
    {
      jobName: 'indexed two faces',
      stock: { length: LENGTH, width: 2 * RADIUS, thickness: 2 * RADIUS },
      materialName: 'softwood',
      zDatum: 'rotary-axis',
      origin: 'topFrontLeft',
      camVersion: '1.0.0',
      toolKey: 'flat-3.175x12-metal',
    },
    Z1,
  );
  if (!posted.ok) throw new Error(`the post refused the fixture: ${posted.errors.join('; ')}`);
  return posted.text;
}

type SimInfo = { status: string; step: number; k: number; turningDeg: number };
const simState = (page: Page): Promise<SimInfo> =>
  page.evaluate(() => {
    const s = window.__caseMaker!.getSimState();
    return { status: s.status, step: s.step, k: s.k, turningDeg: s.turningDeg };
  });

test('an indexed job turns the stock at the index, and a seek across it keeps the step', async ({ cm, page }) => {
  fs.mkdirSync(OUT, { recursive: true });
  fs.mkdirSync(SHOTS, { recursive: true });
  const file = path.join(OUT, 'indexed-two-faces.nc');
  fs.writeFileSync(file, twoFacesGcode());

  await cm.ready();
  await page.getByTestId('welcome-starter-dowel').click();
  await expect(page.getByTestId('start-wizard')).toBeVisible();
  await page.getByTestId('start-wizard-close').click();
  await enterCnc(page, 'cnc-sim');
  await expect(page.getByTestId('sim-panel')).toBeVisible();
  const [chooser] = await Promise.all([page.waitForEvent('filechooser'), page.getByTestId('sim-open').click()]);
  await chooser.setFiles(file);
  await expect(page.getByTestId('sim-rotary-file')).toContainText('the stock is a rod in the rotary chuck');
  await expect(page.getByTestId('sim-stock-diameter')).toHaveValue('20');
  await page.getByTestId('sim-tool').selectOption('flat-3.175x12-metal');
  await page.getByTestId('sim-simulate').click();
  await expect(page.getByTestId('sim-result')).toBeVisible({ timeout: 240_000 });
  await expect(page.getByTestId('sim-backend')).toContainText(/exact/i);
  // An indexed job's material has no map, so the simulation offers no Unroll (#824).
  await expect(page.getByTestId('sim-view-unroll')).toHaveCount(0);

  // The faces from the session's own checkpoints: the first step of the 90° run is the index.
  const faces = await page.evaluate(() => window.__caseMaker!.getSimState().runs);
  const first = faces.find((f) => f.a === 0)!;
  const second = faces.find((f) => f.a === 90)!;
  expect(first).toBeTruthy();
  expect(second).toBeTruthy();
  const inFirst = Math.floor((first.firstStep + first.lastStep) / 2);
  const inSecond = Math.floor((second.firstStep + second.lastStep) / 2);

  await page.evaluate((s: number) => window.__caseMaker!.simSetStep(s), inFirst);
  await page.waitForTimeout(600);
  let st = await simState(page);
  expect(st.step).toBe(inFirst);
  expect(st.turningDeg).toBeCloseTo(0, 6);
  await page.screenshot({ path: path.join(SHOTS, 'face-1-at-0deg.png') });

  // Across the index turn: the sought step, the second face's A, no reset.
  await page.evaluate((s: number) => window.__caseMaker!.simSetStep(s), inSecond);
  await page.waitForTimeout(600);
  st = await simState(page);
  expect(st.step).toBe(inSecond);
  expect(st.turningDeg).toBeCloseTo(90, 6);
  await page.screenshot({ path: path.join(SHOTS, 'face-2-at-90deg.png') });

  // Play from inside face 1 and watch the turn happen at the index.
  await page.evaluate((s: number) => window.__caseMaker!.simSetStep(s), inFirst);
  await page.getByTestId('sim-speed').selectOption('5');
  await page.getByTestId('sim-play').click();
  await expect
    .poll(async () => (await simState(page)).turningDeg, { timeout: 120_000, intervals: [100] })
    .toBeCloseTo(90, 6);
  st = await simState(page);
  expect(st.step).toBeGreaterThan(inFirst);
  await page.screenshot({ path: path.join(SHOTS, 'played-across-index.png') });
});
